def cprint(a):
    print(a)
    pyperclip.copy(a)


def lmap(f, n):
    return list(map(f, n))


def main(inp, is_real):
    inp = inp.strip().split('\n\n')
    inp = [{tuple(map(int, v.split(','))) for v in x.split('\n')[1:]} for x in inp]

    def get_valid_rots():
        for p in permutations(range(3)):
            for sa in (-1, 1):
                for sb in (-1, 1):
                    for sc in (-1, 1):
                        parity = 1 if p in [(0,1,2), (1,2,0), (2,0,1)] else -1
                        parity *= sa * sb * sc
                        if parity == -1:
                            continue
                        yield (p, (sa, sb, sc))
    valid_rots = list(get_valid_rots())

    def apply(rot, x):
        p, mul = rot
        x = tuple(a*b for a, b in zip(mul, x))
        return tuple(x[p[i]] for i in range(3))

    def rotations(s):
        for rot in valid_rots:
            yield {apply(rot, x) for x in s}

    for r in rotations(inp[0]):
        print(r)

    def merge(a, b):
        for rb in rotations(b):
            for pa in a:
                for pb in rb:
                    pos = tuple(xa - xb for xa, xb in zip(pa, pb))
                    tb = {tuple(x+xa-xb for x,xa,xb in zip(p,pa,pb)) for p in rb}
                    assert pa in tb
                    if len(tb & a) >= 12:
                        return (a | tb, pos)

    def get_pos(b):
        for rb in rotations(b):
            pb = next(iter(rb))
            for pa in CORRECT:
                pos = tuple(xa - xb for xa, xb in zip(pa, pb))
                tb = {tuple(x+xa-xb for x,xa,xb in zip(p,pa,pb)) for p in rb}
                assert pa in tb
                if len(tb & CORRECT) == len(tb):
                    return pos

    #locs = [get_pos(b) for b in inp]

    cur_set = inp[0]
    unused = inp[1:]
    locs = [(0,0,0)]
    while unused:
        nxt, *unused = unused
        cnd = merge(cur_set, nxt)
        if cnd is None:
            unused.append(nxt)
        else:
            cur_set = cnd[0]
            locs.append(cnd[1])
        print(cur_set, len(unused), locs)

    ans = len(cur_set)

    cprint(len(cur_set))
    ans = max(sum(abs(x-y) for x,y in zip(a,b)) for a in locs for b in locs)
    cprint(ans)


